mapper.select:
SELECT u.* FROM sys_user u WHERE u.deleted=FALSE AND EXISTS (
    SELECT 1 FROM sys_user_role ur WHERE ur.user_id=u.id AND ur.role_id=#{roleId} AND ur.deleted=FALSE
) ORDER BY u.id FOR UPDATE

mapper.update:
UPDATE sys_user u SET auth_version=auth_version+1 WHERE u.deleted=FALSE AND EXISTS (
    SELECT 1 FROM sys_user_role ur WHERE ur.user_id=u.id AND ur.role_id=#{roleId} AND ur.deleted=FALSE
)
